function ChatView({ notify }) { const [message, setMessage] = useState(''); const messages = [{ person: 'Meera Nair', body: 'The new onboarding brief is ready for review. I linked it to DG-104.', time: '09:42', color: 'violet' }, { person: 'Arjun Kapoor', body: 'Nice. I can add the technical access checklist before the afternoon review.', time: '09:45', color: 'orange' }, { person: 'You', body: 'Perfect. Let’s keep the checklist attached to the task so the context stays together.', time: '09:48', color: 'mint' }]; return <section className="chat-layout"><aside className="chat-sidebar surface-card"><div className="chat-search"><Search size={15} /><input placeholder="Find a conversation" /></div><div className="chat-section-label">Channels</div>{['general', 'leadership', 'growth', 'engineering', 'dialgrow-agents'].map((channel, index) => <button key={channel} className={`channel-row ${index === 1 ? 'channel-active' : ''}`}><Hash size={16} /><span>{channel}</span>{index === 1 && <span className="unread-dot" />}</button>)}<div className="chat-section-label chat-people-label">Direct messages</div>{people.slice(1, 5).map((person) => <button className="dm-row" key={person.id}><Avatar person={person} size="xs" /><span>{person.name}</span><span className="presence-dot" /></button>)}</aside><div className="chat-window surface-card"><div className="chat-window-head"><div><span className="channel-title"><Hash size={17} /> leadership</span><small>4 members · Team channel</small></div><div className="chat-head-actions"><button className="icon-button" title="Start video call" onClick={() => notify('Video rooms are ready to connect')}><Video size={17} /></button><button className="icon-button" title="Search channel"><Search size={17} /></button></div></div><div className="message-stream"><div className="chat-date">Today</div>{messages.map((message) => <div className={`message ${message.person === 'You' ? 'message-own' : ''}`} key={message.time}><Avatar person={message.person === 'You' ? people[0] : message.person} size="sm" /><div><div className="message-meta"><strong>{message.person}</strong><span>{message.time}</span></div><p>{message.body}</p>{message.person === 'Meera Nair' && <div className="message-attachment"><FileText size={15} /><div><strong>onboarding-brief.md</strong><span>Shared document · 24 KB</span></div><ArrowDownRight size={15} /></div>}</div></div>)}</div><form className="message-composer" onSubmit={(event) => { event.preventDefault(); if (message) { setMessage(''); notify('Message sent to #leadership'); } }}><button type="button" className="icon-button"><Plus size={18} /></button><input value={message} onChange={(event) => setMessage(event.target.value)} placeholder="Message #leadership" /><button className="send-button" type="submit"><Send size={16} /></button></form></div></section>; }

function TrainingView({ notify }) { const courses = [{ title: 'DialGrow onboarding essentials', meta: 'Required · 5 modules', progress: 82, color: 'mint', icon: Sparkles }, { title: 'Writing work that can be reviewed', meta: 'Role track · 3 modules', progress: 46, color: 'violet', icon: Pencil }, { title: 'Secure workspace habits', meta: 'Required · 4 modules', progress: 15, color: 'orange', icon: LockKeyhole }]; return <section className="section-stack"><div className="training-hero"><div><div className="eyebrow">Learning center</div><h2>Build capability in the flow of work.</h2><p>Short, useful learning paths that make your next task easier.</p></div><div className="learning-score"><span>This week</span><strong>3.4h</strong><small>learning time</small></div></div><div className="course-grid">{courses.map((course) => <article className="course-card" key={course.title}><div className={`course-icon ${course.color}`}><course.icon size={20} /></div><StatusPill tone={course.progress > 70 ? 'green' : 'gray'}>{course.progress === 100 ? 'COMPLETED' : 'IN PROGRESS'}</StatusPill><h3>{course.title}</h3><p>{course.meta}</p><div className="course-progress"><div className="progress-bar"><span style={{ width: `${course.progress}%` }} /></div><b>{course.progress}%</b></div><button onClick={() => notify(`Opening ${course.title}`)}>{course.progress < 100 ? 'Continue course' : 'Review course'} <ArrowUpRight size={15} /></button></article>)}</div><div className="surface-card training-table"><CardHeader title="Assigned to your role" action="Browse catalog" onAction={() => notify('Training catalog opened')} /><div className="assignment-row"><div className="assignment-icon"><GraduationCap size={18} /></div><div><strong>Giving and receiving feedback</strong><span>Team Lead track · 20 min</span></div><span className="assignment-due">Due Oct 02</span><Button variant="secondary" onClick={() => notify('Training started')}>Start</Button></div><div className="assignment-row"><div className="assignment-icon"><BookOpen size={18} /></div><div><strong>How DialGrow uses permissions</strong><span>Everyone · 12 min</span></div><span className="assignment-due">Due Oct 05</span><Button variant="secondary" onClick={() => notify('Training started')}>Start</Button></div></div></section>; }

