function AuthRouter() {
  const [screen, setScreen] = useState('landing');
  const [session, setSession] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!supabase) { setLoading(false); return undefined; }
    supabase.auth.getSession().then(({ data }) => { setSession(data.session); setLoading(false); });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, nextSession) => setSession(nextSession));
    return () => subscription.unsubscribe();
  }, []);

  if (loading) return <div className="auth-loading"><div className="auth-loader" /><span>Connecting to DialGrow Workspace</span></div>;
  if (session) return <LiveWorkspace session={session} onSignOut={() => supabase?.auth.signOut()} />;
  if (screen === 'login') return <LoginPage onBack={() => setScreen('landing')} />;
  return <LandingPage onLogin={() => setScreen('login')} />;
}

function LandingPage({ onLogin }) {
  return <div className="landing-page"><div className="landing-nav"><BrandLogo dark /><div className="landing-nav-links"><a href="#workspace">Workspace</a><a href="#roles">Role views</a><a href="#security">Security</a></div><button className="landing-login" onClick={onLogin}>Sign in <ArrowRight size={15} /></button></div><main className="landing-main"><section className="landing-hero"><div className="landing-hero-copy"><div className="landing-eyebrow"><span className="hero-pulse" /> DialGrow Workspace · Employee operating system</div><h1>Make the work<br /><span>move together.</span></h1><p>One secure workspace for people, priorities, conversations, knowledge and the next right action.</p><div className="landing-actions"><button className="landing-primary" onClick={onLogin}>Enter your workspace <ArrowRight size={16} /></button><button className="landing-secondary" onClick={() => document.getElementById('workspace')?.scrollIntoView({ behavior: 'smooth' })}>See how it works <ChevronDown size={16} /></button></div><div className="landing-proof"><span><Check size={14} />Role-aware by default</span><span><Check size={14} />Live team context</span><span><Check size={14} />Built for DialGrow</span></div></div><div className="landing-visual" id="workspace"><div className="visual-label"><span className="live-dot live" /> WORKSPACE / TODAY</div><div className="visual-window"><div className="visual-sidebar"><div className="visual-dot" /><div /><div /><div /><div /><div /></div><div className="visual-content"><div className="visual-content-top"><div><span>Good morning, Durga</span><strong>Your operating loop, in one place.</strong></div><span className="visual-avatar">DP</span></div><div className="visual-metrics"><span /><span /><span /></div><div className="visual-grid"><div><div className="visual-line long" /><div className="visual-line" /><div className="visual-line short" /><div className="visual-line" /></div><div className="visual-orbit"><span>AI</span></div></div></div></div><div className="visual-float float-one"><CheckCircle2 size={14} /><span>Task approved</span><b>just now</b></div><div className="visual-float float-two"><MessageSquare size={14} /><span>Team update</span><b>3 new</b></div></div></section><section className="landing-strip" id="roles"><span>One workspace</span><span>Different views</span><span>Shared context</span><span>Clear permissions</span></section><section className="landing-bottom" id="security"><div><span className="landing-eyebrow">A calmer way to operate</span><h2>Everyone sees what matters to them.</h2></div><p>Employees focus on today’s work. Leads get the visibility they need. Admins keep the organization secure and configurable.</p></section></main><footer className="landing-footer"><BrandLogo dark /><span>© 2026 DialGrow. Internal workspace.</span><span>People · Work · Knowledge · Communication</span></footer></div>;
}

function LoginPage({ onBack }) {
  const [mode, setMode] = useState('signin');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [fullName, setFullName] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [message, setMessage] = useState(null);
  const [busy, setBusy] = useState(false);

  const submit = async (event) => {
    event.preventDefault();
    setBusy(true); setMessage(null);
    if (!supabase) { setMessage({ type: 'error', text: 'Supabase is not configured for this deployment.' }); setBusy(false); return; }
    const result = mode === 'signin'
      ? await supabase.auth.signInWithPassword({ email: email.trim().toLowerCase(), password })
      : await supabase.auth.signUp({ email: email.trim().toLowerCase(), password, options: { data: { full_name: fullName } } });
    if (result.error) setMessage({ type: 'error', text: result.error.message });
    else setMessage({ type: 'success', text: mode === 'signin' ? 'Signed in. Loading your workspace...' : 'Account created. Check your email if confirmation is enabled.' });
    setBusy(false);
  };

  const resetPassword = async () => {
    if (!email || !supabase) { setMessage({ type: 'error', text: 'Enter your work email first.' }); return; }
    const { error } = await supabase.auth.resetPasswordForEmail(email.trim().toLowerCase(), { redirectTo: window.location.origin });
    setMessage(error ? { type: 'error', text: error.message } : { type: 'success', text: 'Password reset instructions sent to your work email.' });
  };

  return <div className="auth-page"><section className="auth-brand-panel"><div className="auth-brand-top"><BrandLogo dark /></div><div className="auth-brand-copy"><div className="landing-eyebrow"><span className="hero-pulse" /> Secure internal workspace</div><h1>Work with context.<br /><span>Grow with clarity.</span></h1><p>DialGrow keeps people, priorities and conversations connected so every team can move with confidence.</p><div className="auth-benefits"><span><CheckCircle2 size={17} />One place for daily work</span><span><CheckCircle2 size={17} />Role-aware access</span><span><CheckCircle2 size={17} />Human team updates</span></div></div><div className="auth-brand-footer"><span>© 2026 DialGrow</span><span>Internal use only</span></div></section><section className="auth-form-panel"><button className="auth-back" onClick={onBack}><ChevronRight size={15} className="back-chevron" /> Back to home</button><div className="auth-form-wrap"><div className="auth-form-heading"><div className="mobile-auth-logo"><BrandLogo /></div><span className="landing-eyebrow">DialGrow Workspace</span><h2>{mode === 'signin' ? 'Welcome back' : 'Activate your workspace'}</h2><p>{mode === 'signin' ? 'Enter your details to sign in to your workspace.' : 'Use the email your admin invited to DialGrow.'}</p></div><div className="auth-tabs"><button className={mode === 'signin' ? 'active' : ''} onClick={() => { setMode('signin'); setMessage(null); }}>Sign in</button><button className={mode === 'activate' ? 'active' : ''} onClick={() => { setMode('activate'); setMessage(null); }}>First access</button></div><form className="auth-form" onSubmit={submit}>{mode === 'activate' && <label>Full name<input value={fullName} onChange={(event) => setFullName(event.target.value)} placeholder="Your full name" required /></label>}<label>Work email<input type="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="name@dialgrow.com" autoComplete="email" required /></label><label><span className="label-row">Password{mode === 'signin' && <button type="button" onClick={resetPassword}>Forgot password?</button>}</span><span className="password-input"><input type={showPassword ? 'text' : 'password'} value={password} onChange={(event) => setPassword(event.target.value)} placeholder="Enter your password" autoComplete={mode === 'signin' ? 'current-password' : 'new-password'} minLength={8} required /><button type="button" onClick={() => setShowPassword((value) => !value)} aria-label={showPassword ? 'Hide password' : 'Show password'}>{showPassword ? <EyeOff size={17} /> : <Eye size={17} />}</button></span></label>{message && <div className={`auth-message ${message.type}`}>{message.type === 'success' ? <CheckCircle2 size={15} /> : <CircleUserRound size={15} />}{message.text}</div>}<button className="auth-submit" disabled={busy}>{busy ? 'Connecting...' : mode === 'signin' ? 'Sign in' : 'Create account'} <ArrowRight size={17} /></button></form><div className="auth-no-provider"><span />Employees sign in with their DialGrow account<span /></div><p className="auth-help">Need access? Ask your Main Admin to create your <strong>@dialgrow.com</strong> account.</p></div></section></div>;
}

function LiveWorkspace({ session, onSignOut }) {
  const [workspace, setWorkspace] = useState(null);
  const [activeView, setActiveView] = useState('dashboard');
  const [selectedChannel, setSelectedChannel] = useState(null);
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [toast, setToast] = useState(null);
  const [showTaskForm, setShowTaskForm] = useState(false);
  const [showEmployeeForm, setShowEmployeeForm] = useState(false);

  const notify = (text, type = 'success') => { setToast({ text, type }); window.setTimeout(() => setToast(null), 3400); };
  const refresh = async () => { setLoading(true); try { setWorkspace(await loadWorkspace(session.user)); setError(null); } catch (reason) { setError(reason.message); } finally { setLoading(false); } };

  useEffect(() => { refresh(); }, [session.user.id]);
  useEffect(() => { if (!workspace?.profile?.organization_id) return undefined; recordLogin(session.user, workspace.profile.organization_id).catch(() => undefined); return undefined; }, [workspace?.profile?.organization_id, session.user.id]);
  useEffect(() => {
    if (!workspace?.channels?.length) return undefined;
    const channelId = selectedChannel || workspace.channels[0].id;
    setSelectedChannel(channelId);
    supabase.from('messages').select('*').eq('channel_id', channelId).order('created_at', { ascending: true }).then(({ data }) => setMessages(data || []));
    const realtime = supabase.channel(`workspace-live-${channelId}`).on('postgres_changes', { event: '*', schema: 'public', table: 'messages', filter: `channel_id=eq.${channelId}` }, (payload) => { if (payload.eventType === 'INSERT') setMessages((current) => [...current, payload.new]); }).subscribe();
    return () => { supabase.removeChannel(realtime); };
  }, [workspace?.channels, selectedChannel]);

  const roleName = workspace?.profile?.role?.name || 'Employee';
  const createLiveTask = async (event) => { event.preventDefault(); const form = new FormData(event.currentTarget); const { error: taskError } = await createTask({ organizationId: workspace.profile.organization_id, creatorId: session.user.id, title: form.get('title'), description: form.get('description'), priority: form.get('priority'), assigneeId: session.user.id }); if (taskError) notify(taskError.message, 'error'); else { setShowTaskForm(false); notify('Task created in the live workspace'); refresh(); } };
  const checkIn = async () => { const nextStatus = workspace.attendance?.status === 'working' ? 'checked_out' : 'working'; const { error: attendanceError } = await updateAttendance({ userId: session.user.id, organizationId: workspace.profile.organization_id, status: nextStatus, sessionId: crypto.randomUUID() }); if (attendanceError) notify(attendanceError.message, 'error'); else { notify(nextStatus === 'working' ? 'You are checked in' : 'You are checked out'); refresh(); } };
  const sendLiveMessage = async (event) => { event.preventDefault(); const form = new FormData(event.currentTarget); const body = form.get('body')?.toString().trim(); if (!body || !selectedChannel) return; const { error: messageError } = await sendMessage({ channelId: selectedChannel, authorId: session.user.id, body }); if (messageError) notify(messageError.message, 'error'); else { event.currentTarget.reset(); notify('Message sent'); } };
  const createChannel = async (event) => { event.preventDefault(); const form = new FormData(event.currentTarget); const { error: channelError } = await supabase.from('channels').insert({ organization_id: workspace.profile.organization_id, name: form.get('name'), description: form.get('description'), channel_type: 'team' }); if (channelError) notify(channelError.message, 'error'); else { event.currentTarget.reset(); notify('Team group created'); refresh(); } };
  const createEmployee = async (event) => { event.preventDefault(); const form = new FormData(event.currentTarget); const { data: result, error: invokeError } = await supabase.functions.invoke('create-employee', { body: { fullName: form.get('fullName'), email: form.get('email'), password: form.get('password'), roleName: form.get('roleName') } }); if (invokeError || result?.error) notify(invokeError?.message || result.error, 'error'); else { event.currentTarget.reset(); setShowEmployeeForm(false); notify('Employee credentials created'); refresh(); } };
  const bootstrap = async () => { const { error: bootstrapError } = await supabase.rpc('bootstrap_dialgrow_workspace'); if (bootstrapError) setError(bootstrapError.message); else refresh(); };

  if (loading) return <div className="auth-loading"><div className="auth-loader" /><span>Loading your role and workspace data</span></div>;
  if (error || !workspace?.profile?.organization_id) return <WorkspaceSetup error={error} onRetry={refresh} onBootstrap={session.user.email?.toLowerCase() === 'durga@dialgrow.com' ? bootstrap : null} onSignOut={onSignOut} />;
  const currentView = activeView === 'dashboard' ? <LiveDashboard workspace={workspace} session={session} roleName={roleName} setActiveView={setActiveView} onCheckIn={checkIn} onNotify={notify} /> : activeView === 'tasks' ? <LiveTasks workspace={workspace} onCreate={() => setShowTaskForm(true)} /> : activeView === 'chat' ? <LiveChat workspace={workspace} messages={messages} onSend={sendLiveMessage} onChannelChange={setSelectedChannel} selectedChannel={selectedChannel} /> : activeView === 'calendar' ? <LiveCalendar workspace={workspace} /> : activeView === 'profile' ? <LiveProfile workspace={workspace} session={session} onSaved={() => { notify('Profile updated'); refresh(); }} /> : activeView === 'admin' ? <LiveAdmin workspace={workspace} onCreateEmployee={() => setShowEmployeeForm(true)} onCreateChannel={createChannel} onNotify={notify} /> : <LiveRoleView workspace={workspace} view={activeView} roleName={roleName} onNotify={notify} />;
  return <div className="live-app-shell"><LiveSidebar activeView={activeView} setActiveView={setActiveView} roleName={roleName} onSignOut={onSignOut} /><main className="live-main"><LiveTopbar workspace={workspace} roleName={roleName} setActiveView={setActiveView} /><div className="live-page">{activeView !== 'dashboard' && <div className="live-page-head"><div><span className="landing-eyebrow">Workspace / {activeView}</span><h1>{activeView === 'admin' ? 'Admin center' : activeView[0].toUpperCase() + activeView.slice(1)}</h1><p>{roleName} view · live data from DialGrow Workspace</p></div>{activeView === 'tasks' && <button className="live-action" onClick={() => setShowTaskForm(true)}><Plus size={16} /> Create task</button>}</div>}{currentView}</div></main>{showTaskForm && <LiveTaskModal onClose={() => setShowTaskForm(false)} onSubmit={createLiveTask} />}{showEmployeeForm && <LiveEmployeeModal roles={workspace.roles} onClose={() => setShowEmployeeForm(false)} onSubmit={createEmployee} />}{toast && <div className={`live-toast ${toast.type}`}><CheckCircle2 size={16} />{toast.text}<button onClick={() => setToast(null)}><X size={14} /></button></div>}</div>;
}

function WorkspaceSetup({ error, onRetry, onBootstrap, onSignOut }) { return <div className="setup-page"><BrandLogo /><div className="setup-card"><div className="setup-icon"><RefreshCw size={23} /></div><span className="landing-eyebrow">Live workspace setup</span><h1>One last connection step.</h1><p>{error || 'Your Supabase account is authenticated, but your DialGrow profile is not set up yet.'}</p><div className="setup-steps"><span><b>1</b>Run <code>supabase/schema.sql</code></span><span><b>2</b>Bootstrap the owner account</span><span><b>3</b>Return here and refresh</span></div><div className="setup-actions">{onBootstrap && <button className="live-action" onClick={onBootstrap}><Shield size={15} /> Initialize workspace</button>}<button className="quiet-action" onClick={onRetry}><RefreshCw size={15} /> Retry connection</button><button className="quiet-action" onClick={onSignOut}>Sign out</button></div></div></div>; }

function LiveSidebar({ activeView, setActiveView, roleName, onSignOut }) { const base = roleName === 'Main Admin' ? [{ id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard }, { id: 'tasks', label: 'All tasks', icon: ListTodo }, { id: 'chat', label: 'Chat', icon: MessageSquare }, { id: 'calendar', label: 'Calendar', icon: CalendarDays }, { id: 'people', label: 'Employees', icon: Users }, { id: 'admin', label: 'Admin center', icon: Shield }] : roleName === 'Operations Lead' ? [{ id: 'dashboard', label: 'Operations home', icon: Gauge }, { id: 'tasks', label: 'Operations queue', icon: ListTodo }, { id: 'chat', label: 'Team chat', icon: MessageSquare }, { id: 'calendar', label: 'Attendance calendar', icon: CalendarDays }, { id: 'reports', label: 'Reports', icon: Activity }] : roleName.includes('Technical') || roleName.includes('Developer') ? [{ id: 'dashboard', label: 'Technical home', icon: Gauge }, { id: 'tasks', label: 'Technical tasks', icon: ListTodo }, { id: 'chat', label: 'Engineering chat', icon: MessageSquare }, { id: 'calendar', label: 'Sprint calendar', icon: CalendarDays }, { id: 'training', label: 'Learning', icon: GraduationCap }] : [{ id: 'dashboard', label: 'My dashboard', icon: LayoutDashboard }, { id: 'tasks', label: 'My tasks', icon: ListTodo }, { id: 'chat', label: 'Chat', icon: MessageSquare }, { id: 'calendar', label: 'My calendar', icon: CalendarDays }, { id: 'documents', label: 'Documents', icon: FileText }]; return <aside className="live-sidebar"><div className="live-sidebar-brand"><BrandLogo /><span className="live-sidebar-status"><span className="live-dot live" /> Live</span></div><div className="live-role-card"><span className="role-card-mark"><Shield size={16} /></span><div><strong>{roleName}</strong><span>Role dashboard</span></div><ChevronDown size={14} /></div><nav className="live-nav"><span className="live-nav-label">Workspace</span>{base.map(({ id, label, icon: Icon }) => <button key={id} className={activeView === id ? 'active' : ''} onClick={() => setActiveView(id)}><Icon size={17} /><span>{label}</span></button>)}<span className="live-nav-label connect-label">Account</span><button className={activeView === 'profile' ? 'active' : ''} onClick={() => setActiveView('profile')}><CircleUserRound size={17} /><span>My profile</span></button></nav><div className="live-sidebar-foot"><div className="privacy-note"><LockKeyhole size={14} /><span>Access is scoped to your role</span></div><button className="signout-button" onClick={onSignOut}><LogOut size={15} /> Sign out</button></div></aside>; }

function LiveTopbar({ workspace, roleName, setActiveView }) { const profile = workspace.profile; return <header className="live-topbar"><div className="live-breadcrumb"><span>DialGrow</span><ChevronRight size={14} /><strong>{roleName}</strong></div><div className="live-top-actions"><button className="live-search"><Search size={16} /><span>Search workspace</span><kbd>⌘ K</kbd></button><button className="live-icon-button" onClick={() => setActiveView('chat')}><MessageSquare size={17} /><i /></button><button className="live-icon-button"><Bell size={17} /></button><button className="live-user-menu" onClick={() => setActiveView('profile')}><span className="live-user-avatar">{profile.full_name.split(/\s+/).map((part) => part[0]).join('').slice(0, 2).toUpperCase()}</span><span><strong>{profile.full_name}</strong><small>{profile.email}</small></span><ChevronDown size={14} /></button></div></header>; }

function LiveDashboard({ workspace, roleName, setActiveView, onCheckIn, onNotify }) { const tasks = workspace.tasks || []; const open = tasks.filter((task) => !['completed', 'archived'].includes(task.status)).length; const review = tasks.filter((task) => ['under_review', 'submitted'].includes(task.status)).length; const working = workspace.attendance?.status === 'working'; const mode = roleName === 'Main Admin' ? 'admin' : roleName === 'Operations Lead' ? 'operations' : roleName.includes('Technical') || roleName.includes('Developer') ? 'technical' : roleName === 'Team Lead' ? 'team' : 'employee'; const greeting = mode === 'admin' ? 'Organization control center' : mode === 'operations' ? 'Daily operations, in view' : mode === 'technical' ? 'Technical work, in flow' : mode === 'team' ? 'Your team, moving together' : 'Your workday, with context'; const tasksForUser = tasks.slice(0, 5); return <section className="live-dashboard"><div className={`role-hero role-hero-${mode}`}><div><span className="landing-eyebrow"><span className="live-dot live" /> {roleName} dashboard</span><h2>{greeting}</h2><p>{mode === 'admin' ? 'Configure people, roles, teams and the operating system behind DialGrow.' : mode === 'operations' ? 'Keep check-ins, exceptions and daily execution visible without adding noise.' : mode === 'technical' ? 'Review the work, resources and learning path behind technical delivery.' : mode === 'team' ? 'See the team workload, review queue and next conversations in one place.' : 'See your priorities, deadlines, learning and conversations without switching systems.'}</p></div><div className="role-hero-actions"><span className={`live-attendance ${working ? 'working' : ''}`}><span className="status-dot" />{working ? 'Working now' : 'Not checked in'}</span><button onClick={onCheckIn}>{working ? 'Check out' : 'Check in'}</button></div></div><div className="live-metric-grid"><LiveMetric label={mode === 'admin' ? 'Workspace tasks' : 'My open tasks'} value={open} detail="Live from Supabase" icon={ListTodo} color="mint" /><LiveMetric label={mode === 'team' ? 'Review queue' : 'Needs attention'} value={review} detail="Waiting for action" icon={ClipboardCheck} color="blue" /><LiveMetric label="Today\'s login" value={workspace.logins?.[0] ? new Date(workspace.logins[0].created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '—'} detail={workspace.profile.timezone || 'Local workspace time'} icon={Clock3} color="orange" /><LiveMetric label="Teams" value={workspace.teams?.length || 0} detail="Your current scope" icon={Users} color="violet" /></div><div className="live-dashboard-grid"><div className="live-panel"><div className="live-panel-head"><div><span className="landing-eyebrow">Execution</span><h3>{mode === 'admin' ? 'Organization work' : mode === 'team' ? 'Team work' : 'Your next work'}</h3></div><button onClick={() => setActiveView('tasks')}>Open tasks <ArrowUpRight size={14} /></button></div>{tasksForUser.length ? <div className="live-task-list">{tasksForUser.map((task) => <div className="live-task-item" key={task.id}><span className={`live-task-state state-${task.status}`} /><div><strong>{task.title}</strong><span>{task.reference || task.id.slice(0, 8)} · {task.priority || 'medium'} priority</span></div><span className="live-task-date">{task.due_date || 'No due date'}</span></div>)}</div> : <LiveEmpty title="No tasks yet" body="When work is assigned to you, it will appear here with its full context." action="Create a task" onClick={() => setActiveView('tasks')} />}</div><div className="live-panel live-signal-panel"><div className="live-panel-head"><div><span className="landing-eyebrow">Workspace pulse</span><h3>Human signals, not noise</h3></div><span className="signal-live"><span className="live-dot live" /> Live</span></div><div className="live-signal-list"><LiveSignal icon={MessageSquare} title="Team messages" detail={`${workspace.channels?.length || 0} groups available`} onClick={() => setActiveView('chat')} /><LiveSignal icon={CalendarDays} title="Work schedule" detail={`${workspace.profile.work_start_time || '09:30'} - ${workspace.profile.work_end_time || '18:30'} · ${workspace.profile.timezone || 'Asia/Kolkata'}`} onClick={() => setActiveView('calendar')} /><LiveSignal icon={Bot} title="Priya Sharma" detail="Human-style weekly team updates" onClick={() => onNotify('Priya Sharma will post updates through the live team channels')} /></div></div></div>{mode === 'admin' && <div className="live-admin-callout"><div className="admin-callout-icon"><Shield size={19} /></div><div><strong>Admin controls are live</strong><p>Create employee accounts, configure roles and create groups from the Admin center.</p></div><button onClick={() => setActiveView('admin')}>Open Admin center <ArrowUpRight size={14} /></button></div>}</section>; }
function LiveMetric({ label, value, detail, icon: Icon, color }) { return <div className="live-metric"><span className={`live-metric-icon ${color}`}><Icon size={17} /></span><div><span>{label}</span><strong>{value}</strong><small>{detail}</small></div></div>; }
function LiveSignal({ icon: Icon, title, detail, onClick }) { return <button className="live-signal" onClick={onClick}><span><Icon size={16} /></span><div><strong>{title}</strong><small>{detail}</small></div><ChevronRight size={15} /></button>; }
function LiveEmpty({ title, body, action, onClick }) { return <div className="live-empty"><Inbox size={20} /><strong>{title}</strong><p>{body}</p>{action && <button onClick={onClick}>{action} <ArrowRight size={14} /></button>}</div>; }

function LiveTasks({ workspace, onCreate }) { return <section className="live-view-stack"><div className="live-filter-row"><span><span className="live-dot live" /> Live tasks</span><button className="quiet-action"><Filter size={14} /> Filter</button></div><div className="live-panel live-tasks-panel"><div className="live-table-head"><span>Task</span><span>Status</span><span>Priority</span><span>Due</span></div>{workspace.tasks.length ? workspace.tasks.map((task) => <div className="live-table-row" key={task.id}><div><strong>{task.title}</strong><small>{task.reference || task.id.slice(0, 8)} · {task.description || 'No description'}</small></div><StatusPill tone={task.status === 'completed' ? 'green' : task.status === 'blocked' ? 'red' : task.status === 'under_review' ? 'blue' : 'amber'} dot>{(task.status || 'assigned').replaceAll('_', ' ').toUpperCase()}</StatusPill><span>{task.priority || 'medium'}</span><span>{task.due_date || 'No due date'}</span></div>) : <LiveEmpty title="Your task list is clear" body="Live tasks assigned through DialGrow will appear here." action="Create your first task" onClick={onCreate} />}</div></section>; }

function LiveChat({ workspace, messages, onSend, onChannelChange, selectedChannel }) { return <section className="live-chat-layout"><aside className="live-channel-list live-panel"><div className="live-panel-head"><div><span className="landing-eyebrow">Connect</span><h3>Team groups</h3></div><span className="live-count">{workspace.channels.length}</span></div>{workspace.channels.map((channel) => <button className={selectedChannel === channel.id ? 'selected' : ''} key={channel.id} onClick={() => onChannelChange(channel.id)}><Hash size={15} /><span>{channel.name}</span><ChevronRight size={14} /></button>)}{!workspace.channels.length && <LiveEmpty title="No groups yet" body="Your admin can create the first team group." />}</aside><div className="live-chat-window live-panel"><div className="live-chat-head"><div><span className="landing-eyebrow">Team conversation</span><h2><Hash size={19} />{workspace.channels.find((channel) => channel.id === selectedChannel)?.name || 'Select a group'}</h2></div><span className="live-secure"><LockKeyhole size={13} /> Scoped access</span></div><div className="live-message-list">{messages.length ? messages.map((message) => <div className={`live-message ${message.author_id === workspace.profile.id ? 'own' : ''}`} key={message.id}><span className="live-message-avatar">{message.author_id === workspace.profile.id ? 'ME' : 'TM'}</span><div><span><strong>{message.author_id === workspace.profile.id ? workspace.profile.full_name : 'Team member'}</strong>{new Date(message.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span><p>{message.body}</p></div></div>) : <LiveEmpty title="Start the conversation" body="Messages posted here are stored live in your Supabase workspace." />}</div>{selectedChannel && <form className="live-message-form" onSubmit={onSend}><input name="body" placeholder="Write to your team..." /><button><Send size={16} /></button></form>}</div></section>; }

function LiveCalendar({ workspace }) { const today = new Date(); return <section className="live-calendar-grid"><div className="live-panel live-calendar-card"><div className="live-panel-head"><div><span className="landing-eyebrow">Calendar</span><h3>{today.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })}</h3></div><span className="calendar-timezone">{workspace.profile.timezone || 'Asia/Kolkata'}</span></div><div className="schedule-banner"><Clock3 size={16} /><div><strong>Your working hours</strong><span>{workspace.profile.work_start_time || '09:30'} - {workspace.profile.work_end_time || '18:30'} · Monday to Friday</span></div></div><div className="calendar-days">{Array.from({ length: 7 }, (_, index) => { const date = new Date(today); date.setDate(today.getDate() - today.getDay() + index + 1); return <div className={date.toDateString() === today.toDateString() ? 'today' : ''} key={date.toISOString()}><span>{date.toLocaleDateString(undefined, { weekday: 'short' })}</span><strong>{date.getDate()}</strong><i /></div>; })}</div><div className="login-history"><div className="live-panel-head"><h3>Login history</h3><span>Last 8 sessions</span></div>{workspace.logins?.length ? workspace.logins.map((login) => <div className="login-history-row" key={login.id}><span className="status-dot" /><div><strong>{new Date(login.created_at).toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' })}</strong><small>{login.metadata?.timezone || workspace.profile.timezone || 'Local time'}</small></div><b>{new Date(login.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</b></div>) : <LiveEmpty title="No login history yet" body="Your next successful sign-in will be recorded here." />}</div></div><div className="live-panel calendar-note"><span className="calendar-note-icon"><Bot size={18} /></span><span className="landing-eyebrow">Priya Sharma</span><h3>Team updates will land here.</h3><p>Three times each week between 4:00 and 5:00 PM, Priya Sharma will share a human-style update for your team. Fridays include a weekly update prompt.</p></div></section>; }

function LiveProfile({ workspace, session, onSaved }) { const [name, setName] = useState(workspace.profile.full_name); const [start, setStart] = useState(workspace.profile.work_start_time || '09:30'); const [end, setEnd] = useState(workspace.profile.work_end_time || '18:30'); const save = async (event) => { event.preventDefault(); const { error } = await supabase.from('profiles').update({ full_name: name, work_start_time: start, work_end_time: end }).eq('id', session.user.id); if (error) window.alert(error.message); else onSaved(); }; return <section className="live-profile-grid"><div className="live-panel profile-card"><div className="profile-avatar-large">{name.split(/\s+/).map((part) => part[0]).join('').slice(0, 2).toUpperCase()}</div><span className="landing-eyebrow">{workspace.profile.role?.name || 'Employee'}</span><h2>{name}</h2><p>{workspace.profile.email}</p><StatusPill tone="green" dot>ACTIVE ACCOUNT</StatusPill></div><form className="live-panel profile-form" onSubmit={save}><div className="live-panel-head"><div><span className="landing-eyebrow">Personal settings</span><h3>Keep your details current</h3></div><Button type="submit">Save changes</Button></div><label>Full name<input value={name} onChange={(event) => setName(event.target.value)} /></label><label>Work email<input value={workspace.profile.email} readOnly /></label><div className="profile-time-row"><label>Workday starts<input type="time" value={start} onChange={(event) => setStart(event.target.value)} /></label><label>Workday ends<input type="time" value={end} onChange={(event) => setEnd(event.target.value)} /></label></div><div className="profile-security-note"><LockKeyhole size={15} /><span>Authentication is managed by Supabase Auth. Your login times and profile changes are audited.</span></div></form></section>; }

function LiveRoleView({ workspace, view, roleName, onNotify }) { const labels = { people: ['People in scope', 'People and teams visible to your role.'], reports: ['Reports', 'Transparent signals from live workspace data.'], training: ['Learning', 'Training assignments and progress for your role.'], documents: ['Documents', 'Permission-aware knowledge for your current scope.'] }; const content = labels[view] || [roleName, 'This role surface is ready for live data from your workspace.']; return <section className="live-placeholder live-panel"><div className="live-placeholder-icon"><Sparkles size={20} /></div><span className="landing-eyebrow">Live module</span><h2>{content[0]}</h2><p>{content[1]}</p><button className="live-action" onClick={() => onNotify('This module is connected to Supabase and ready for records')}><Zap size={15} /> Check connection</button></section>; }

function LiveAdmin({ workspace, onCreateEmployee, onCreateChannel, onNotify }) { const roles = workspace.roles.length ? workspace.roles : Object.entries(roleDefaults).map(([name, item]) => ({ id: name, name, ...item })); return <section className="live-admin-page"><div className="admin-live-header"><div><span className="landing-eyebrow"><span className="live-dot live" /> Main Admin control plane</span><h2>Configure the people and permissions behind DialGrow.</h2><p>Changes made here are written to Supabase and become visible to the right role immediately.</p></div><div className="admin-live-actions"><button className="live-action" onClick={onCreateEmployee}><UserPlus size={15} /> Create employee</button><button className="quiet-action" onClick={() => document.getElementById('create-group')?.scrollIntoView({ behavior: 'smooth' })}><Plus size={15} /> Create group</button></div></div><div className="live-admin-grid"><div className="live-panel"><div className="live-panel-head"><div><span className="landing-eyebrow">Roles</span><h3>Role capability directory</h3></div><span className="live-count">{roles.length}</span></div><div className="live-role-list">{roles.map((role) => <div className="live-role-row" key={role.id}><span className="role-card-mark"><Shield size={15} /></span><div><strong>{role.name}</strong><small>{role.layer || 'Custom'} · {role.description || 'Configured workspace role'}</small><span>{(role.responsibilities || []).slice(0, 2).join(' · ') || 'Permission-based access'}</span></div><ChevronRight size={15} /></div>)}</div></div><div className="live-panel" id="create-group"><div className="live-panel-head"><div><span className="landing-eyebrow">Groups and teams</span><h3>Create a team group</h3></div></div><form className="live-inline-form" onSubmit={onCreateChannel}><label>Group name<input name="name" placeholder="e.g. customer-success" required /></label><label>Description<input name="description" placeholder="What is this group for?" /></label><button className="live-action" type="submit"><Plus size={15} /> Create group</button></form><div className="live-created-list">{workspace.channels.map((channel) => <span key={channel.id}><Hash size={13} />{channel.name}</span>)}</div></div></div><div className="live-panel admin-audit"><div className="live-panel-head"><div><span className="landing-eyebrow">Governance</span><h3>Live audit surface</h3></div><button onClick={() => onNotify('Audit records are stored in Supabase audit_logs')}>How it works <ArrowUpRight size={14} /></button></div><div className="audit-row"><CheckCircle2 size={16} /><span>Login times recorded per user</span><StatusPill tone="green">LIVE</StatusPill></div><div className="audit-row"><CheckCircle2 size={16} /><span>Role changes are scoped and traceable</span><StatusPill tone="green">LIVE</StatusPill></div><div className="audit-row"><CheckCircle2 size={16} /><span>Employee credentials created server-side</span><StatusPill tone="green">EDGE FUNCTION</StatusPill></div></div></section>; }

function LiveTaskModal({ onClose, onSubmit }) { return <div className="live-modal-backdrop"><form className="live-modal" onSubmit={onSubmit}><button type="button" className="live-modal-close" onClick={onClose}><X size={17} /></button><span className="landing-eyebrow">Live work item</span><h2>Create a task</h2><p>It will be stored in the active DialGrow organization.</p><label>Task title<input name="title" placeholder="What needs to happen?" required autoFocus /></label><label>Context<textarea name="description" rows="3" placeholder="Give the assignee enough context to act." /></label><label>Priority<select name="priority" defaultValue="medium"><option value="urgent">Urgent</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select></label><div className="live-modal-actions"><button type="button" className="quiet-action" onClick={onClose}>Cancel</button><button className="live-action" type="submit"><Plus size={15} /> Create task</button></div></form></div>; }
function LiveEmployeeModal({ roles, onClose, onSubmit }) { return <div className="live-modal-backdrop"><form className="live-modal" onSubmit={onSubmit}><button type="button" className="live-modal-close" onClick={onClose}><X size={17} /></button><span className="landing-eyebrow">Admin · new employee</span><h2>Create DialGrow credentials</h2><p>The account is created through the protected Supabase Edge Function.</p><label>Full name<input name="fullName" placeholder="Employee name" required /></label><label>DialGrow email<input name="email" type="email" placeholder="name@dialgrow.com" pattern=".+@dialgrow\\.com" required /></label><label>Temporary password<input name="password" type="password" placeholder="At least 10 characters" minLength="10" required /></label><label>Role<select name="roleName" defaultValue={roles[0]?.name}>{roles.map((role) => <option key={role.id} value={role.name}>{role.name}</option>)}</select></label><div className="live-modal-actions"><button type="button" className="quiet-action" onClick={onClose}>Cancel</button><button className="live-action" type="submit"><UserPlus size={15} /> Create account</button></div></form></div>; }

createRoot(document.getElementById('root')).render(<AuthRouter />);
